"use client";

import type { ComponentProps } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BADGE_SIZE, useBarSize } from "./barSize";

/**
 * src/components/badge.tsx — a plain, stock shadcn Badge. Not vendored
 * anywhere else in this repo (checked apps/docs and packages/inspector —
 * absent from both), so this is written fresh rather than ported; it's a
 * small, extremely standard shadcn primitive with nothing repo-specific to
 * preserve. No `asChild`/Slot support — this app has no reason yet to
 * render a Badge as a link, and skipping it avoids a new dependency.
 *
 * WHY `size` was added here (stock shadcn's Badge has none): the Bar size
 * cascade (barSize.tsx) needs somewhere to land on Badge, and there was no
 * existing scale to hook into. Four rungs, matching `Bar`'s own directly.
 *
 * WHY `shape` defaults to `"rounded"` rather than flipping to pill
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-1, Zach: "show some badges with a
 * more pill shape"): he asked to *see* the pill option, not replace the
 * landed look — every existing caller (in particular `Bar`'s title badge,
 * which reads as a chip on purpose) must render unchanged. `rounded-full`
 * is opt-in via `shape="pill"`, not the new floor.
 */
const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border font-medium whitespace-nowrap transition-[color,box-shadow] [&>svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive: "border-transparent bg-destructive text-white dark:bg-destructive/60",
        outline: "text-foreground",
      },
      size: {
        sm: "gap-0.5 px-1.5 py-0 text-[0.65rem] [&>svg]:size-2.5",
        md: "gap-1 px-2 py-0.5 text-xs [&>svg]:size-3",
        lg: "gap-1 px-2.5 py-1 text-sm [&>svg]:size-3.5",
        xl: "gap-1.5 px-3 py-1 text-base [&>svg]:size-4",
      },
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
      shape: "rounded",
    },
  },
);

export interface BadgeProps extends ComponentProps<"span">, VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, size, shape, ...props }: BadgeProps) {
  // Explicit `size` wins; the ambient Bar cascade is only the fallback when
  // `size` itself is omitted, `"md"` (cva's own default) is the floor when
  // there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BADGE_SIZE[barSize]) ?? "md";
  return (
    <span
      data-slot="badge"
      data-size={resolvedSize}
      data-shape={shape ?? "rounded"}
      className={cn(badgeVariants({ variant, size: resolvedSize, shape }), className)}
      {...props}
    />
  );
}

export { badgeVariants };

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

// src/components/breadcrumb.tsx — shadcn base-nova copy, ported from
// /home/bam/systemsketch/src/components/ui/breadcrumb.tsx:1-114 (itself a
// stock shadcn `new-york` Breadcrumb — plain semantic elements, no Base UI
// primitive backs a breadcrumb trail), `cn` repointed to this app's own
// `../lib/utils`.
import type * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { ChevronRightIcon, MoreHorizontalIcon } from "lucide-react";

import { cn } from "../lib/utils";

function Breadcrumb({ className, ...props }: React.ComponentProps<"nav">) {
  return <nav aria-label="breadcrumb" data-slot="breadcrumb" className={cn(className)} {...props} />;
}

function BreadcrumbList({ className, ...props }: React.ComponentProps<"ol">) {
  return (
    <ol
      data-slot="breadcrumb-list"
      className={cn("flex flex-wrap items-center gap-1.5 text-sm wrap-break-word text-muted-foreground", className)}
      {...props}
    />
  );
}

function BreadcrumbItem({ className, ...props }: React.ComponentProps<"li">) {
  return <li data-slot="breadcrumb-item" className={cn("inline-flex items-center gap-1", className)} {...props} />;
}

function BreadcrumbLink({ className, render, ...props }: useRender.ComponentProps<"a">) {
  return useRender({
    defaultTagName: "a",
    props: mergeProps<"a">(
      {
        className: cn("transition-colors hover:text-foreground", className),
      },
      props,
    ),
    render,
    state: {
      slot: "breadcrumb-link",
    },
  });
}

function BreadcrumbPage({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      className={cn("font-normal text-foreground", className)}
      {...props}
    />
  );
}

function BreadcrumbSeparator({ children, className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      className={cn("[&>svg]:size-3.5", className)}
      {...props}
    >
      {children ?? <ChevronRightIcon />}
    </li>
  );
}

// WHY this is a real menu, not decoration (docs/menus/MENU-KIT-DESIGN.md §5,
// "the `…` is a real menu of hidden levels"): `compactDepthBreadcrumbs`
// (ported into `breadcrumbCompact.ts` by another lane) elides middle path
// segments under a character budget, and the elided names still have to be
// reachable — this component only renders the glyph; the host wires a
// `DropdownMenu`/`ContextMenu` off it with the elided crumbs as items.
function BreadcrumbEllipsis({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      className={cn("flex size-5 items-center justify-center [&>svg]:size-4", className)}
      {...props}
    >
      <MoreHorizontalIcon />
      <span className="sr-only">More</span>
    </span>
  );
}

export { Breadcrumb, BreadcrumbEllipsis, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator };

/**
 * src/components/breadcrumbCompact.ts — the compact-path elision rule behind
 * the depth breadcrumb (docs/menus/screenshots/05, the SystemSketch TitleBar's
 * `…` disclosure).
 *
 * `compactDepthBreadcrumbs` is ported verbatim from
 * /home/bam/systemsketch/src/depth/depthBreadcrumbs.ts:1-58 (zero imports,
 * already generic over `{id,name,isCurrent}`). `segmentBreadcrumbs` below is
 * a generalized port of the same file's `segmentBreadcrumbs` helper at
 * /home/bam/systemsketch/src/chrome/TitleBar.tsx:130-160: the donor hardcodes
 * `DepthPathEntry` (which carries a tldraw `TLShapeId`); here it is generic
 * over any `Entry extends DepthBreadcrumbItem`, which is what lets this file
 * import zero canvas-engine types while still recovering the elided run for
 * each `…` disclosure menu, the way `TitleBar.tsx` needs to.
 */

export interface DepthBreadcrumbItem {
  kind?: never
  id: string
  name: string
  isCurrent: boolean
}

export type CompactDepthBreadcrumbItem<Entry extends DepthBreadcrumbItem = DepthBreadcrumbItem> =
  | Entry
  | { kind: "elision"; hiddenCount: number }

const CHARACTER_BUDGET = 150
const SEPARATOR_LENGTH = 3 // ` › `

function pathLength(rootName: string, entries: readonly DepthBreadcrumbItem[]) {
  return rootName.length + entries.reduce((total, entry) => total + SEPARATOR_LENGTH + entry.name.length, 0)
}

/**
 * Keeps the compact chrome useful as a location cue, rather than turning it
 * into a left- or right-truncated filename. The root, immediate parent, and
 * current scope orient a reader; levels immediately after the root are the
 * least useful first removals, while the disclosure retains every ancestor as
 * a jump target.
 */
export function compactDepthBreadcrumbs<Entry extends DepthBreadcrumbItem>(
  rootName: string,
  entries: readonly Entry[],
  budget = CHARACTER_BUDGET,
): CompactDepthBreadcrumbItem<Entry>[] {
  if (pathLength(rootName, entries) <= budget || entries.length < 3) return [...entries]

  const visible = new Set(entries.map((entry) => entry.id))
  // WHY: Keep the root plus immediate local context legible. When space runs
  // out, the earliest descendant is the least actionable location cue, so
  // delete from level 1 forward rather than surprising the reader by hiding a
  // nearer parent.
  for (const entry of entries.slice(0, -2)) {
    if (pathLength(rootName, entries.filter((candidate) => visible.has(candidate.id))) <= budget) break
    visible.delete(entry.id)
  }

  const compacted = entries.filter((entry) => visible.has(entry.id))
  if (compacted.length === entries.length) return compacted

  const result: CompactDepthBreadcrumbItem<Entry>[] = []
  let hiddenCount = 0
  for (const entry of entries) {
    if (visible.has(entry.id)) {
      if (hiddenCount) {
        result.push({ kind: "elision", hiddenCount })
        hiddenCount = 0
      }
      result.push(entry)
    } else {
      hiddenCount += 1
    }
  }
  return result
}

function isElision<Entry extends DepthBreadcrumbItem>(
  entry: CompactDepthBreadcrumbItem<Entry>,
): entry is { kind: "elision"; hiddenCount: number } {
  return typeof entry === "object" && entry !== null && "kind" in entry && entry.kind === "elision"
}

export type CrumbSegment<Entry extends DepthBreadcrumbItem = DepthBreadcrumbItem> =
  | { kind: "entry"; entry: Entry }
  | { kind: "elision"; hidden: Entry[] }

/**
 * `compactDepthBreadcrumbs` reports only how MANY levels it dropped, because
 * the shipped pill draws a dead `…` and sends people to the depth popover for
 * the rest. The Kibo pattern makes that ellipsis a real menu, so the hidden
 * levels have to be recovered — the compacted list keeps source order, so each
 * elision's `hiddenCount` names exactly the next run of skipped entries.
 */
export function segmentBreadcrumbs<Entry extends DepthBreadcrumbItem>(
  rootName: string,
  entries: readonly Entry[],
): CrumbSegment<Entry>[] {
  const segments: CrumbSegment<Entry>[] = []
  let cursor = 0
  for (const item of compactDepthBreadcrumbs(rootName, entries)) {
    if (isElision(item)) {
      segments.push({ kind: "elision", hidden: entries.slice(cursor, cursor + item.hiddenCount) })
      cursor += item.hiddenCount
    } else {
      segments.push({ kind: "entry", entry: item })
      cursor += 1
    }
  }
  return segments
}

// src/components/button-group.tsx — copied from
// apps/docs/src/registry/new-york-v4/ui/button-group.tsx (the stock shadcn
// `new-york` ButtonGroup over Base UI's `useRender`/`mergeProps`), `cn` and
// `Separator` import paths repointed to this app (components/ and lib/ are
// siblings here, not `@/registry/...`).
"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import type * as React from "react";

import { cn } from "../lib/utils";
import { Separator } from "./separator";

const buttonGroupVariants = cva(
  "has-[>[data-slot=button-group]]:gap-2 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-lg flex w-fit items-stretch *:focus-visible:relative *:focus-visible:z-10 [&>[data-slot=select-trigger]:not([class*='w-'])]:w-fit [&>input]:flex-1",
  {
    variants: {
      orientation: {
        horizontal:
          "[&>[data-slot]:not(:has(~[data-slot]))]:rounded-r-lg! *:data-slot:rounded-r-none [&>[data-slot]~[data-slot]]:rounded-l-none [&>[data-slot]~[data-slot]]:border-l-0",
        vertical:
          "[&>[data-slot]:not(:has(~[data-slot]))]:rounded-b-lg! flex-col *:data-slot:rounded-b-none [&>[data-slot]~[data-slot]]:rounded-t-none [&>[data-slot]~[data-slot]]:border-t-0",
      },
    },
    defaultVariants: {
      orientation: "horizontal",
    },
  },
);

function ButtonGroup({
  className,
  orientation,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof buttonGroupVariants>) {
  return (
    <div
      role="group"
      data-slot="button-group"
      data-orientation={orientation}
      className={cn(buttonGroupVariants({ orientation }), className)}
      {...props}
    />
  );
}

function ButtonGroupText({ className, render, ...props }: useRender.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(
          "bg-muted gap-2 rounded-lg border px-2.5 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 flex items-center [&_svg]:pointer-events-none",
          className,
        ),
      },
      props,
    ),
    render,
    state: {
      slot: "button-group-text",
    },
  });
}

function ButtonGroupSeparator({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="button-group-separator"
      orientation={orientation}
      // WHY `data-[orientation=...]:` rather than the donor's bare
      // `data-horizontal:`/`data-vertical:` (measured bug, same root cause
      // documented in this app's own separator.tsx): Base UI's Separator
      // sets a single `orientation` STATE key, which its generic
      // state→attribute mapping renders as `data-orientation="vertical"` —
      // never a bare `data-horizontal`/`data-vertical` presence attribute.
      // The stock registry file's selectors target an attribute the DOM
      // never has, so they were dead CSS; this app's `separator.tsx` and
      // `toolbar.tsx`'s `ToolbarSeparator` already fixed the same bug at
      // their own sites, this is the third.
      className={cn(
        "bg-input relative self-stretch data-[orientation=horizontal]:mx-px data-[orientation=horizontal]:w-auto data-[orientation=vertical]:my-px data-[orientation=vertical]:h-auto",
        className,
      )}
      {...props}
    />
  );
}

export { ButtonGroup, ButtonGroupSeparator, ButtonGroupText, buttonGroupVariants };

"use client";

// src/components/button.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/button.tsx (the stock shadcn `new-york`
// Button over Base UI), only the `cn` import path changed to match this app,
// plus the Bar size cascade (barSize.tsx) below.
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BUTTON_SIZE, useBarSize } from "./barSize";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Button({
  className,
  variant = "default",
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  // Explicit `size` wins; the ambient Bar cascade (barSize.tsx) is only the
  // fallback when `size` itself is omitted, `"default"` (this component's
  // original default) is the floor when there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BUTTON_SIZE[barSize]) ?? "default";
  return (
    <ButtonPrimitive
      data-slot="button"
      data-size={resolvedSize}
      className={cn(buttonVariants({ variant, size: resolvedSize, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

// src/components/chromeBar.tsx — the top-left bar (docs/menus/screenshots/
// 05-chrome-bar.png, 09-draft-title-bar.png's bottom row). Ported from
// /home/bam/systemsketch/src/chrome/TitleBar.tsx:1-630 — the burger →
// back/forward → breadcrumb → draft chip → depth badge cluster, minus every
// tldraw/editor/depth-model dependency the donor pulls in (`useEditor`,
// `subscribeDepthNavigation`, `useDepthHistoryInputs`, `useDocumentIdentity`).
// The bar's own shape — one `Toolbar.Root` owning the separators and roving
// focus, `FileAction[]` feeding both the dropdown AND the context menu so
// they cannot drift, `data-active` as a presence test on the draft chip, the
// ellipsis-is-a-real-menu breadcrumb — travels verbatim; only the state that
// travelled through tldraw hooks becomes plain props (docs/menus/
// MENU-KIT-DESIGN.md §4, "Chrome bar" host contract).
//
// `segmentBreadcrumbs`/`compactDepthBreadcrumbs` (the character-budget
// elision behind the `…` disclosure) are lane E's `breadcrumbCompact.ts`,
// itself ported from /home/bam/systemsketch/src/depth/depthBreadcrumbs.ts and
// TitleBar.tsx:130-160 — not reimplemented here.
