} from "lucide-react";

import { cn } from "../lib/utils";
import { badgeVariants } from "./badge";
import {
  Breadcrumb,
  BreadcrumbEllipsis,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "./breadcrumb";
import { segmentBreadcrumbs, type DepthBreadcrumbItem } from "./breadcrumbCompact";
import { Button } from "./button";
import { ButtonGroup } from "./button-group";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuGroup,
