/**
 * bbox-ui EditableText layout — the portable geometry of the text-leaf.
 *
 * EditableText's own size ladder, deliberately NOT `layout.ts`'s `TEXT_SIZES`
 * (frozen for T1) and NOT `Glyph`'s or `Port`'s own independent ladders —
 * see docs/T1-SPEC.md §0 on why three components each get their own 18px
 * "small" rung rather than one shared file. React-free, engine-free, same
 * discipline as `layout.ts`.
 *
 * PROVENANCE: OURS, AD HOC. NO PRIOR ART IS CLAIMED, and this file has no
 * donor — stated explicitly rather than left as an absence, because an
 * uncited file is ambiguous between "written here" and "nobody wrote down
 * where this came from", and only one of those is true.
 *
 * There is also no algorithm here to have prior art FOR. Every export is a
 * lookup table or a total `Record` over a string union: the size ladder, the
 * three font stacks, and the two align→flex maps. The one function with a
 * rule in it, `editableTextFontPx`, is a single ternary. The CSS values on
 * the right-hand side of those Records (`flex-start`/`center`/`flex-end`)
 * are of course the CSS Flexbox spec's, but this file does not implement
 * them — it names them and hands them to the browser, which is not a
 * citation-bearing act. The reason the tables are TOTAL Records rather than
 * ternaries is a real decision and it is documented at each seam below.
 */

/** EditableText's own ladder. Values match the board's own Text Size row. */
export const EDITABLE_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
// WHY `EditableTextSize` widens by union rather than `EDITABLE_TEXT_SIZES` growing a
// fifth rung: "custom" has no single px value — it is the ESCAPE from the
// named ladder into `sizePx`, so it cannot live in a `Record<name, px>` the
// way sm/md/lg/xl do. `editableTextFontPx` below is the one place that resolves
// either shape back to a number. See docs/TEXTBOX-EDITING-SPEC.md §1.
export type EditableTextSize = keyof typeof EDITABLE_TEXT_SIZES | "custom";

/** The font-size in px for a given `size`/`sizePx` pair — the one function
 * that knows "custom" escapes the named ladder. `sizePx` is ignored for the
 * four named rungs, exactly like `font`/`align` ignore props that don't
 * apply to them. */
export function editableTextFontPx(size: EditableTextSize, sizePx: number): number {
  return size === "custom" ? sizePx : EDITABLE_TEXT_SIZES[size];
}

// WHY the array is the source and the type is derived: annotating the field
// table stopped the SCHEMA advertising a value the component cannot render,
// but not the reverse — widening the union and adding its stack left the
// panel silently offering three of four fonts with the suite green. With one
// runtime array behind both, a test can pin the field's options to it and
// catch growth in either direction. Same shape as BLOCK_ORIENTATIONS.
export const EDITABLE_TEXT_FONTS = ["sans", "sketch", "mono"] as const;
export type EditableTextFont = (typeof EDITABLE_TEXT_FONTS)[number];
export const EDITABLE_TEXT_FONT_STACKS: Record<EditableTextFont, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
  sketch: '"Segoe Print", "Bradley Hand", cursive',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
};

type FlexPlacement = "flex-start" | "center" | "flex-end";

// WHY total Records rather than the ternaries these replace: deriving the
// union from the array made widening it reach the panel automatically, which
// is what we wanted — but a ternary has a fall-through, so a new member
// arrived as a live segment that silently rendered `center`, typecheck clean
// and every test green. A total Record is what makes the array the real
// source: adding a member is a compile error until someone says where it
// lays out. The same shape as EDITABLE_TEXT_FONT_STACKS, which is why `font`
// already failed loudly and these two did not.
export const EDITABLE_TEXT_VERTICAL_ALIGNS = ["top", "middle", "bottom"] as const;
export type EditableTextVerticalAlign = (typeof EDITABLE_TEXT_VERTICAL_ALIGNS)[number];
export const EDITABLE_TEXT_ALIGN_ITEMS: Record<EditableTextVerticalAlign, FlexPlacement> = {
  top: "flex-start",
  middle: "center",
  bottom: "flex-end",
};
export function editableTextAlignItems(align: EditableTextVerticalAlign): FlexPlacement {
  return EDITABLE_TEXT_ALIGN_ITEMS[align];
}

export const EDITABLE_TEXT_HORIZONTAL_ALIGNS = ["left", "middle", "right"] as const;
export type EditableTextHorizontalAlign = (typeof EDITABLE_TEXT_HORIZONTAL_ALIGNS)[number];
export const EDITABLE_TEXT_JUSTIFY_CONTENT: Record<EditableTextHorizontalAlign, FlexPlacement> = {
  left: "flex-start",
  middle: "center",
  right: "flex-end",
};
export function editableTextJustifyContent(justify: EditableTextHorizontalAlign): FlexPlacement {
  return EDITABLE_TEXT_JUSTIFY_CONTENT[justify];
}

/**
 * src/components/glyph.layout.ts — ported by value from
 * packages/bbox-ui/src/glyph.layout.ts (Glyph v2, docs/GLYPH-PLAN.md's
 * contract). Same size ladder and override-vs-preset rule; this app has no
 * `layout.ts`/`TEXT_SIZES` of its own to stay independent of, but the
 * ladder is kept in its own file anyway so `glyph.tsx` matches its source
 * shape 1:1 for anyone diffing the two later.
 *
 * DONOR LINES (read 2026-09-17; the donor is 53 lines and lives in this
 * same repo, so this is a `diff` away, not an archaeology dig):
 *   • `glyph.layout.ts:11`    `GLYPH_SIZES` — same four rungs, same values.
 *   • `glyph.layout.ts:20-43` the two interfaces.
 *   • `glyph.layout.ts:45-52` `glyphFootprint`, including the `!== undefined`
 *     rule restated below. Arithmetic unchanged.
 *
 * NO PRIOR ART IS CLAIMED, and none applies: the "ladder plus override"
 * rule and the square `size + 2*padding` footprint are this repo's own
 * product decisions, not an algorithm. There is nothing here to cite but
 * the donor.
 */
export const GLYPH_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type GlyphSize = keyof typeof GLYPH_SIZES;
export const GLYPH_SIZE_NAMES: Record<GlyphSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

export interface GlyphFootprintInput {
  sizePreset?: GlyphSize;
  /** px override — when given, wins over `sizePreset`. */
  size?: number;
  padding?: number;
}

export interface GlyphFootprint {
  /** Resolved side length of the glyph itself, px. */
  size: number;
  padding: number;
  /** Outer box a host places on canvas — `size + 2*padding`, square. */
  w: number;
  h: number;
}

/**
 * The override-vs-preset size rule, in one place. `size` absent/undefined
 * is NOT the same as `size: 0` — an explicit 0 is a real override, so this
 * checks `!== undefined`, never falsy/`??`, to keep that case distinguishable.
 */
export function glyphFootprint({
  sizePreset = "sm",
  size,
  padding = 0,
}: GlyphFootprintInput): GlyphFootprint {
  const resolvedSize = size !== undefined ? size : GLYPH_SIZES[sizePreset];
  const outer = resolvedSize + 2 * padding;
  return { size: resolvedSize, padding, w: outer, h: outer };
}

// src/components/inlineRename.tsx — ours, ported behavior. The commit
// contract (Enter/Escape/blur, the double-click mousedown guard, the
// empty-name refusal message) is ported from
// /home/bam/systemsketch/src/drafts/DraftsControl.tsx:36-116 (its local
// `InlineRename` helper) and cross-checked against the near-duplicate at
// /home/bam/systemsketch/src/drafts/DraftModeBar.tsx:394-423 — this file
// REPLACES both (docs/menus/MENU-KIT-DESIGN.md §3.1: "one component
// replacing the two duplicated editors"). `validate` generalizes the
// donor's hardcoded empty-name check into a swappable policy so the file
// rename / frames-row rename call sites (which want different messages,
// not different mechanics) don't need a third copy.
"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";

import { cn } from "../lib/utils";

/**
 * How long a rename input's own `mousedown` is swallowed after it mounts.
 *
 * WHY (ported, DraftsControl.tsx:22-28): `InlineRename` focuses and
 * text-selects itself on mount, so a user's HABITUAL double-click's second
 * click lands ~90-200ms later on this now-different element — the
 * freshly-mounted `<input>`, not whatever trigger opened it. No native
 * `dblclick` can ever fire (the two clicks hit different elements), so this
 * is a plain click-inside-a-focused-input, which collapses the just-made
 * selection to a caret; the user then types expecting to replace the
 * selected text and instead inserts mid-word. Swallowing a `mousedown`
 * within this window keeps the selection intact for a rapid second click,
 * while a deliberate slow one still places a caret normally. Same window,
 * same root cause, and (per the donor's own comment) the same fix applied
 * at every sibling site — SystemSketch's house rule is to fix a bug
 * everywhere the pattern exists, not only the reported instance.
 */
const RENAME_MOUSEDOWN_GUARD_MS = 400;

function defaultValidate(next: string): string | null {
  // WHY this exact copy ("Give this draft a name.") as the shared default
  // rather than a generic "Name required": it is the donor's own message,
  // reused verbatim at both DraftsControl.tsx:73 and DraftModeBar.tsx:236 —
  // callers that need different wording (the frames row, the file title)
  // pass their own `validate`.
  return next.trim() ? null : "Give this draft a name.";
}

export interface InlineRenameProps {
  value: string;
  onCommit(next: string): void;
  onCancel(): void;
  /** Returns an error message or `null`; default rejects empty. Validation
   *  POLICY is host-swappable — the mechanics (Enter/Escape/blur) are not. */
  validate?: (next: string) => string | null;
  /** Controlled error, for an async commit that can fail after Enter has
   *  already closed the local error state — e.g. a rename that round-trips
   *  through a server. Takes precedence over the internal validation error
   *  while set. */
  error?: string | null;
  /** `"bar"` (chrome bar, draft-mode bar) is denser than `"row"` (frames
   *  panel row, list rows) — see barSize.tsx for the same two-rung idea
   *  applied elsewhere in this kit. */
  size?: "bar" | "row";
  className?: string;
  "aria-label"?: string;
}

const SIZE_CLASS: Record<NonNullable<InlineRenameProps["size"]>, string> = {
  bar: "h-7 rounded-md px-2 text-sm",
  row: "h-6 rounded px-1.5 text-sm",
};

/**
 * A text field that commits on Enter/blur and reverts on Escape.
 *
 * Renders: draft rename (bar + row), frames-panel rename, the branch chip
 * (docs/menus/screenshots/05-chrome-bar.png). Controlled `value`/callbacks
 * only — no F2 keybinding. WHY no keybinding lives here
 * (docs/menus/MENU-KIT-DESIGN.md, "Chrome bar" host-contract section): F2 is
 * a GLOBAL gesture the host wires onto whatever "begin renaming this thing"
 * callback opens the editing state that mounts this component — the same
 * way mouse-buttons-3/4 and BrowserBack/Forward are host gestures, never
 * something a leaf field owns.
 */
export function InlineRename({
  value,
  onCommit,
  onCancel,
  validate = defaultValidate,
  error: externalError,
  size = "row",
  className,
  "aria-label": ariaLabel,
}: InlineRenameProps) {
  const [draft, setDraft] = useState(value);
  const [internalError, setInternalError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const mountedAtRef = useRef(0);
  const helpId = useId();

  useEffect(() => {
    mountedAtRef.current = performance.now();
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  const error = externalError ?? internalError;

  const commit = useCallback(() => {
    const next = draft.trim();
    const message = validate(next);
    if (message) {
      setInternalError(message);
      // A frame late, same as the donor: `requestAnimationFrame` because a
      // `setState` from inside a blur/keydown handler hasn't re-rendered yet.
      window.requestAnimationFrame(() => inputRef.current?.focus());
      return;
    }
    // WHY unchanged text cancels rather than commits (DraftsControl.tsx:76):
    // an Enter/blur on an untouched field isn't a rename, it's a dismiss —
    // calling `onCommit` for it would round-trip a no-op write through
    // whatever the host's commit does (a server call, a history entry).
    if (next !== value) onCommit(next);
    else onCancel();
  }, [draft, onCancel, onCommit, validate, value]);

  return (
    <div data-slot="inline-rename" data-size={size} data-error={error ? "true" : undefined} className="inline-flex flex-col gap-1">
      <input
        ref={inputRef}
        data-slot="inline-rename-input"
        aria-label={ariaLabel ?? "Rename"}
        aria-describedby={helpId}
        aria-invalid={error ? true : undefined}
        value={draft}
        className={cn(
          "border-input bg-background focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 w-full min-w-0 rounded-lg border outline-none focus-visible:ring-3 aria-invalid:ring-3",
          SIZE_CLASS[size],
          className,
        )}
        onChange={(event) => {
          setDraft(event.target.value);
          setInternalError(null);
        }}
        onMouseDown={(event) => {
          if (performance.now() - mountedAtRef.current < RENAME_MOUSEDOWN_GUARD_MS) {
            // Suppresses native caret placement while leaving focus (and the
            // selection `select()` above just made) intact — a rapid second
            // click leaves the text still fully selected, so typing replaces
            // it. A deliberate SLOW second click, outside the window, places
            // a caret normally.
            event.preventDefault();
          }
        }}
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            commit();
          } else if (event.key === "Escape") {
            event.preventDefault();
            // WHY `stopPropagation` (ported, DraftsControl.tsx:98-101): a
            // popover/dialog's own dismissable-layer Escape handler listens
            // on the same bubble path — without this, Escape here closed
            // the WHOLE popup instead of just cancelling the rename.
            event.stopPropagation();
            onCancel();
          }
        }}
        onBlur={commit}
      />
      <span id={helpId} className="text-muted-foreground data-[error=true]:text-destructive text-xs" data-error={error ? "true" : undefined}>
        {error ?? "Press Enter to rename, Escape to cancel"}
      </span>
    </div>
  );
}

// src/components/separator.tsx — based on apps/docs/src/registry/new-york-v4/
// ui/separator.tsx (the stock shadcn `new-york` Separator over Base UI's
// Separator primitive), NOT copied verbatim: that file's own
// `data-horizontal:`/`data-vertical:` classes are dead code. Verified against
// the real runtime (Separator.js sets a single `orientation` STATE key, and
// Base UI's generic state→attribute mapping — getStateAttributesProps.js —
// turns a non-boolean state value into `data-{key}="{value}"`, i.e.
// `data-orientation="horizontal"|"vertical"`, never a bare `data-horizontal`/
// `data-vertical` presence attribute) and against Tailwind's own compiler
// (`data-horizontal:` lowers to the attribute-presence selector
// `[data-horizontal]`, confirmed by compiling it — that selector can never
// match `[data-orientation=horizontal]`). `data-[orientation=…]:` is the
// selector that actually reads the DOM Base UI produces; `toolbar.tsx`'s
// `ToolbarSeparator` already uses this same corrected form, so this fixes
// the two files to agree rather than importing the stock copy's bug into a
// second place. `cn` import path also changed to match this app's own
// src/lib/utils.ts. This is the plain-CSS hairline used for bar dividers and
// grouped rows; a toolbar's own hairline is `toolbar.tsx`'s
// `ToolbarSeparator` instead — it wraps this same primitive but participates
// in the toolbar's roving-focus DOM structure, which a bare `Separator`
// doesn't.
"use client";

import { Separator as SeparatorPrimitive } from "@base-ui/react/separator";

import { cn } from "../lib/utils";

function Separator({ className, orientation = "horizontal", ...props }: SeparatorPrimitive.Props) {
  return (
    <SeparatorPrimitive
      data-slot="separator"
      orientation={orientation}
      className={cn(
        "shrink-0 bg-border data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full data-[orientation=vertical]:w-px data-[orientation=vertical]:self-stretch",
        className,
      )}
      {...props}
    />
  );
}

export { Separator };

// src/components/toolbar.tsx — shadcn has no toolbar item in any style
// (verified 404 twice against the shadcn/ui and base-nova registries), so
// this is a new wrapper, not a copy — over Base UI's `@base-ui/react/toolbar`
// (`Toolbar.Root/Group/Button/Separator/Link`, verified against the real
// package: apps/storybook-basics/node_modules/@base-ui/react/toolbar/
// index.parts.d.ts), styled in the same shadcn/Tailwind idiom as every other
// L1 part here (`cn` + shadcn CSS variables, no raw `style={{color}}`).
"use client";

import { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BUTTON_SIZE, useBarSize, type ButtonToggleSize } from "./barSize";

/**
 * `Toolbar` is the roving-focus container underneath the floating pill
 * (screenshot 01), the bottom tool dock (04), the top-left chrome bar (05)
 * and the status strip — every one of those surfaces is "a row of buttons
 * where arrow keys move focus and only one stop is ever tab-reachable",
 * which is exactly Base UI's `Toolbar.Root` contract (roving tabindex +
 * arrow-key navigation + `loopFocus`) rather than a plain flex row of
 * `Button`s. Anything that composes a `Bar` with tool buttons in one of its
 * slots wants a `Toolbar` in that slot, not raw buttons.
 *
 * WHY it also publishes size via `useBarSize` (barSize.tsx), exactly like
 * `button.tsx`: a toolbar's buttons should size themselves off the ambient
 * Bar the toolbar sits inside (Zach's size-cascade ask, see bar.tsx) without
 * every call site re-passing `size` to every `ToolbarButton`. `size` here is
 * read-only plumbing for the caller's OWN buttons (see `ToolbarButton`
 * below) — the cascade travels through context already mounted by `Bar`,
 * this component does not re-provide it.
 */
function Toolbar({ className, ...props }: ToolbarPrimitive.Root.Props) {
  return (
    <ToolbarPrimitive.Root
      data-slot="toolbar"
      className={cn(
        "flex items-center gap-1 outline-none data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
        className,
      )}
      {...props}
    />
  );
}

function ToolbarGroup({ className, ...props }: ToolbarPrimitive.Group.Props) {
  return (
    <ToolbarPrimitive.Group
      data-slot="toolbar-group"
      className={cn("flex items-center gap-1", className)}
      {...props}
    />
  );
}

/**
 * Renders a `<button>` by default, styled to match `button.tsx`'s own
 * `ghost` "icon" look (toolbar buttons are near-always icon-only — the
 * fill/hatched/transparent cells in screenshot 01, the cursor/frame/shape
 * tools in 04). A consumer that wants the FULL `Button` (variants, the
 * `Bar` size cascade already resolved, `render`-based composition with a
 * `DropdownMenuTrigger`, etc.) passes `render={<Button .../>}` — same seam
 * `DropdownMenuTrigger`/`TooltipTrigger` already use — rather than this
 * component growing a second copy of `buttonVariants`.
 *
 * `size` is accepted only to resolve the ambient Bar cascade for THIS
 * button's own touch target (`h-7`/`h-8`/`h-9`) when the caller renders the
 * plain built-in button rather than composing `Button`; it is stripped
 * before reaching the DOM node.
 */
function ToolbarButton({
  className,
  size,
  ...props
}: ToolbarPrimitive.Button.Props & { size?: ButtonToggleSize }) {
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BUTTON_SIZE[barSize]) ?? "default";
  return (
    <ToolbarPrimitive.Button
      data-slot="toolbar-button"
      data-size={resolvedSize}
      className={cn(
        // WHY `aria-pressed:` rather than a `data-pressed` attribute: Base
        // UI's `Toolbar.Button` has no built-in pressed state of its own
        // (that's `toggle.tsx`'s job, and a toolbar tool button IS just an
        // `aria-pressed` button — screenshot 04's blue cursor tool) — the
        // consumer sets `aria-pressed` and the style follows for free,
        // matching `toggle.tsx`'s own `aria-pressed:bg-muted` convention.
        "inline-flex shrink-0 items-center justify-center gap-1.5 rounded-lg text-sm font-medium whitespace-nowrap outline-none transition-all select-none hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-pressed:bg-primary aria-pressed:text-primary-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        resolvedSize === "sm" && "h-7 px-2",
        resolvedSize === "default" && "h-8 px-2.5",
        resolvedSize === "lg" && "h-9 px-2.5",
        className,
      )}
      {...props}
    />
  );
}

function ToolbarLink({ className, ...props }: ToolbarPrimitive.Link.Props) {
  return (
    <ToolbarPrimitive.Link
      data-slot="toolbar-link"
      className={cn(
        "text-primary text-sm underline-offset-4 outline-none hover:underline focus-visible:ring-3 focus-visible:ring-ring/50",
        className,
      )}
      {...props}
    />
  );
}

/**
 * WHY a plain `bg-border` bar rather than reusing `separator.tsx`'s
 * `Separator`: Base UI's own `Toolbar.Separator` (this wraps it) already
 * carries the toolbar-specific default — vertical in a horizontal toolbar,
 * horizontal in a vertical one — and participates in the roving-focus
 * DOM structure the plain `Separator` primitive doesn't know about.
 * Screenshot 04's dock draws exactly this: a hairline between the tool
 * group and the trailing `+`.
 */
function ToolbarSeparator({ className, ...props }: ToolbarPrimitive.Separator.Props) {
  return (
    <ToolbarPrimitive.Separator
      data-slot="toolbar-separator"
      className={cn(
        "bg-border shrink-0 self-stretch data-[orientation=vertical]:mx-1 data-[orientation=vertical]:w-px data-[orientation=horizontal]:my-1 data-[orientation=horizontal]:h-px",
        className,
      )}
      {...props}
    />
  );
}

export { Toolbar, ToolbarButton, ToolbarGroup, ToolbarLink, ToolbarSeparator };

// src/components/tooltip.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/tooltip.tsx (the stock shadcn
// `new-york` Tooltip over Base UI's Tooltip primitive). packages/inspector
// also has a tooltip.tsx, but it's coupled to the dock's own portal
// container and z-index stack (`dockPortalContainer()`, `z-[320]`) — plumbing
// this standalone app doesn't have, so the docs version is the cleaner,
// self-contained pick. Only the `cn` import path changed to match this
// app's own src/lib/utils.ts.
"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";

import { cn } from "../lib/utils";

function TooltipProvider({ delay = 0, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delay={delay} {...props} />;
}

function Tooltip({ ...props }: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  side = "top",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  anchor,
  collisionPadding,
  container,
  children,
  ...props
}: TooltipPrimitive.Popup.Props &
  // WHY `anchor` was added to this Pick (2026-09-18, menu kit build): same
  // reason as dropdown-menu.tsx's matching edit — a canvas-anchored hint (a
  // pointer-position tooltip with no DOM trigger) needs Positioner's own
  // `anchor` (a Floating UI VirtualElement), which this Pick never
  // surfaced. Adds-only; every current consumer that omits `anchor` is
  // unaffected.
  //
  // `collisionPadding` and `container` followed in the same pass that fixed
  // dropdown-menu.tsx — see the longer note there. The pair has to stay in
  // lockstep across these two files: a host that scopes its design tokens
  // to a container element and gets themed MENUS but unthemed TOOLTIPS has
  // a bug that is much harder to read than one where neither works.
  Pick<
    TooltipPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
  > &
  Pick<TooltipPrimitive.Portal.Props, "container">) {
  return (
    <TooltipPrimitive.Portal container={container}>
      <TooltipPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={cn(
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-[state=delayed-open]:animate-in data-[state=delayed-open]:fade-in-0 data-[state=delayed-open]:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs has-data-[slot=kbd]:pr-1.5 **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-sm data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-fit max-w-xs origin-(--transform-origin) bg-foreground text-background",
            className,
          )}
          {...props}
        >
          {children}
          <TooltipPrimitive.Arrow className="size-2.5 translate-y-[calc(-50%-2px)] rotate-45 rounded-[2px] data-[side=inline-end]:top-1/2! data-[side=inline-end]:-left-1 data-[side=inline-end]:-translate-y-1/2 data-[side=inline-start]:top-1/2! data-[side=inline-start]:-right-1 data-[side=inline-start]:-translate-y-1/2 z-50 bg-foreground fill-foreground data-[side=bottom]:top-1 data-[side=left]:top-1/2! data-[side=left]:-right-1 data-[side=left]:-translate-y-1/2 data-[side=right]:top-1/2! data-[side=right]:-left-1 data-[side=right]:-translate-y-1/2 data-[side=top]:-bottom-2.5" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
